-- Chriz BG Script Engine runtime. Generated by tools/build_runtime.py from the authored
-- modules in this repository; edit those, then rebuild.
-- Builds on Sword Coast Stratagems (DavidW) and Spell Revisions (Demivrgvs, Gibberlings Three).
local factories,loaded={},{}
local function require(name)
  if loaded[name] then return loaded[name] end
  local value=assert(factories[name],'unbundled module')(require)
  loaded[name]=value;return value
end
factories["adapters.eeex.recorder"]=function(require)
-- Optional player-side playtest recorder. It observes the current session and writes JSONL; it
-- neither queues actions nor exports anything into BGSE's combat modules. The one hidden menu is
-- the clock because its enabled callback still runs while the world is paused.
local M={}
M.sightRange=448
M.ticksPerSecond=15
M.fightQuietTicks=6*M.ticksPerSecond
M.rowLimit=500000
M.spellLists={{'mage','m_memorizedSpellsMage',9},{'priest','m_memorizedSpellsPriest',7},
    {'innate','m_memorizedSpellsInnate',1}}
M.itemSlots=39
M.castActions={[31]=true,[95]=true,[113]=true,[114]=true,[181]=true,[191]=true,[192]=true,[337]=true}
M.spellPrefixes={'SPPR','SPWI','SPIN','SPCL'}

local function finite(value)
    return type(value)=='number' and value==value and value~=math.huge and value~=-math.huge
end
local function safeString(value)
    return type(value)=='string' and value:match('^[^%z]*') or ''
end
local function upper(value) return safeString(value):upper() end
local function getString(value)
    if value==nil then return '' end
    local ok,text=pcall(function() return value:get() end)
    return ok and safeString(text) or ''
end
local function sortedKeys(t)
    local keys={}
    for key in pairs(t) do keys[#keys+1]=key end
    table.sort(keys,function(a,b) return tostring(a)<tostring(b) end)
    return keys
end

-- Values sent by the engine's trace sinks must be detached from their owner before logging. This
-- also keeps accidental userdata/functions out of JSON and makes the serializer testable alone.
function M.copy(value,seen)
    local kind=type(value)
    if kind=='string' then return safeString(value) end
    if kind=='number' then return finite(value) and value or nil end
    if kind=='boolean' then return value end
    if kind~='table' then return nil end
    seen=seen or {}
    if seen[value] then return nil end
    seen[value]=true
    local result={}
    for key,child in pairs(value) do
        if type(key)=='string' or finite(key) then
            local copied=M.copy(child,seen)
            if copied~=nil then result[key]=copied end
        end
    end
    seen[value]=nil
    return result
end

local function jsonString(value)
    return '"'..value:gsub('[%z\1-\31\\"]',function(char)
        local byte=char:byte()
        if char=='\\' then return '\\\\' end
        if char=='"' then return '\\"' end
        if char=='\n' then return '\\n' end
        if char=='\r' then return '\\r' end
        if char=='\t' then return '\\t' end
        return string.format('\\u%04x',byte)
    end)..'"'
end
function M.json(value)
    local kind=type(value)
    if kind=='nil' then return 'null' end
    if kind=='boolean' then return value and 'true' or 'false' end
    if kind=='number' then return finite(value) and string.format('%.14g',value) or 'null' end
    if kind=='string' then return jsonString(safeString(value)) end
    if kind~='table' then return 'null' end
    -- Every empty table the recorder emits is a collection (actions, foes, spells, items or an
    -- empty detached trace row), never a structured object with required empty fields.
    if next(value)==nil then return '[]' end
    local length=#value
    local array=length>0
    if array then
        for key in pairs(value) do
            if type(key)~='number' or key<1 or key>length or key%1~=0 then array=false;break end
        end
    end
    local out={}
    if array then
        for index=1,length do out[#out+1]=M.json(value[index]) end
        return '['..table.concat(out,',')..']'
    end
    for _,key in ipairs(sortedKeys(value)) do
        out[#out+1]=jsonString(tostring(key))..':'..M.json(value[key])
    end
    return '{'..table.concat(out,',')..'}'
end

function M.sameQueue(left,right)
    if left==right then return true end
    if type(left)~='table' or type(right)~='table' or #left~=#right then return false end
    for index=1,#left do
        local a,b=left[index],right[index]
        if a.id~=b.id or a.resource~=b.resource or M.json(a.target)~=M.json(b.target) then return false end
    end
    return true
end

function M.cloneQueue(queue)
    local result={}
    for index,row in ipairs(queue) do result[index]={id=row.id,resource=row.resource,target=M.copy(row.target)} end
    return result
end

local function itemMap(member)
    local result={}
    for _,item in ipairs(member.items or {}) do result[item.slot]=item end
    return result
end
local function spellMap(member)
    local result={}
    for _,spell in ipairs(member.spells or {}) do result[spell.list..':'..spell.resref..':'..spell.level]=spell.ready or 0 end
    return result
end

-- The pure end-of-fight debit: differences are deliberately only positive. A newly gained potion
-- or spell slot is not reported as a spend.
function M.spent(startMembers,endMembers)
    local after={}
    for _,member in ipairs(endMembers) do after[member.id]=member end
    local result={}
    for _,before in ipairs(startMembers) do
        local now=after[before.id] or {id=before.id,name=before.name,items={},spells={}}
        local spells={}
        local remaining=spellMap(now)
        for _,spell in ipairs(before.spells or {}) do
            local key=spell.list..':'..spell.resref..':'..spell.level
            local used=(spell.ready or 0)-(remaining[key] or 0)
            if used>0 then spells[#spells+1]={resref=spell.resref,list=spell.list,level=spell.level,count=used} end
        end
        local items={}
        local remainingItems=itemMap(now)
        for _,item in ipairs(before.items or {}) do
            local current=remainingItems[item.slot]
            local beforeUses=item.uses or {}
            local afterUses=current and current.uses or {0,0,0}
            local used={}
            for index=1,3 do
                local debit=(beforeUses[index] or 0)-(afterUses[index] or 0)
                if debit>0 then used[index]=debit end
            end
            if next(used) then items[#items+1]={resref=item.resref,slot=item.slot,
                uses={used[1] or 0,used[2] or 0,used[3] or 0}} end
        end
        if #spells>0 or #items>0 then result[#result+1]={name=before.name,spells=spells,items=items} end
    end
    return result
end

local Root={}
Root.__index=Root
local function gameOf(g)
    local chitin=rawget(g,'EEex_EngineGlobal_CBaldurChitin')
    local globals=rawget(g,'EngineGlobals')
    if not chitin and globals then chitin=globals.g_pBaldurChitin end
    return chitin and chitin.m_pObjectGame or nil
end
local function clock(g)
    local game=gameOf(g)
    return game and game.m_worldTime and game.m_worldTime.m_gameTime or nil
end
local function stat(g,sprite,index)
    local value=g.EEex_Sprite_GetStat(sprite,index)
    return finite(value) and value or 0
end
local function areaOf(sprite)
    return sprite.m_pArea and upper(getString(sprite.m_pArea.m_resref)) or ''
end
local function resrefOf(sprite) return upper(getString(sprite.m_resref)) end
local function nameOf(g,sprite) return safeString(g.EEex_Sprite_GetName(sprite)) end
local function living(g,sprite)
    local state=sprite and sprite.m_baseStats and sprite.m_baseStats.m_generalState
    return finite(state) and g.EEex_BAnd(state,0xFC0)==0
end

-- A numeric SPELL.IDS value is present for some casts whose action string is empty. Keep this
-- plain conversion separate from EEex reads so the convention can be tested without the game.
function M.spellOf(action,resource)
    if resource~='' then return resource end
    if not M.castActions[action.m_actionID] then return '' end
    local number=action.m_specificID
    if type(number)=='number' and number>=1000 and number<5000 and number%1==0 then
        return M.spellPrefixes[math.floor(number/1000)]..string.format('%03d',number%1000)
    end
    return ''
end

function Root:disable(reason)
    if self.disabled then return end
    self.disabled=tostring(reason)
    print('[BGSE recorder] disabled: '..self.disabled)
    if self.file then pcall(self.file.flush,self.file) end
end
function Root:guard(label,fn,...)
    if self.disabled then return false end
    local ok,result=pcall(fn,...)
    if not ok then self:disable(label..': '..tostring(result));return false end
    return result
end
function Root:now()
    local tick=clock(self.g)
    if not finite(tick) then error('game clock unavailable') end
    self.lastTick=tick
    return tick
end
function Root:open()
    if self.file then return end
    local ioLib=self.g.io or io
    local osLib=self.g.os or os
    if type(ioLib)~='table' or type(ioLib.open)~='function' then error('Lua file I/O unavailable') end
    self.fileIndex=self.fileIndex+1
    local stamp=type(osLib.date)=='function' and osLib.date('%Y%m%d-%H%M%S') or 'unknown-time'
    local suffix=self.fileIndex==1 and '' or string.format('-%03d',self.fileIndex)
    local file,err=ioLib.open('bgse-playtest/'..stamp..suffix..'.jsonl','a')
    if not file then error('open recording: '..tostring(err)) end
    self.file=file;self.rows=0
end
function Root:direct(row)
    self.file:write(M.json(row)..'\n')
    self.rows=self.rows+1
end
function Root:emit(row)
    if self.disabled then return end
    self:open()
    if self.rows>=M.rowLimit then
        self.file:flush();self.file:close();self.file=nil
        self:open()
        local continued=M.copy(self.sessionSeed or {})
        continued.k='session';continued.t=row.t;continued.continued=true
        self:direct(continued)
    end
    self:direct(row)
end
function Root:flush(force)
    if not self.file then return end
    local osLib=self.g.os or os
    local now=type(osLib)=='table' and type(osLib.time)=='function' and osLib.time() or 0
    if force or now~=self.lastFlush then
        self.file:flush();self.lastFlush=now
    end
end
function Root:party()
    local count=self.g.EEex_Sprite_GetNumCharacters()
    if not finite(count) then return {} end
    local party={}
    count=math.min(6,math.max(0,math.floor(count)))
    for index=0,count-1 do
        local sprite=self.g.EEex_Sprite_GetInPortrait(index)
        if sprite and finite(sprite.m_id) then party[#party+1]={id=sprite.m_id,sprite=sprite} end
    end
    return party
end
function Root:spells(sprite)
    local rows,index={},{}
    for _,spec in ipairs(M.spellLists) do
        local listName,field,levels=spec[1],spec[2],spec[3]
        local lists=sprite[field]
        if lists then
            for level=0,levels-1 do
                self.g.EEex_Utility_IterateCPtrList(lists:getReference(level),function(spell)
                    local resref=upper(getString(spell.m_spellId))
                    if resref=='' then return end
                    local key=listName..':'..resref..':'..(level+1)
                    local row=index[key]
                    if not row then row={list=listName,resref=resref,level=level+1,ready=0};index[key]=row;rows[#rows+1]=row end
                    if (spell.m_flags or 0)%2==1 then row.ready=row.ready+1 end
                end)
            end
        end
    end
    return rows
end
function Root:items(sprite)
    local equipment=sprite.m_equipment
    local all,equipped,quick,quiver,pack={},{},{},{},{},{}
    if not equipment or not equipment.m_items then return all,equipped,quick,quiver,pack end
    for slot=0,M.itemSlots-1 do
        local item=equipment.m_items:get(slot)
        if item then
            local resref=upper(getString(item.cResRef))
            if resref~='' then
                local row={slot=slot,resref=resref,uses={item.m_useCount1 or 0,item.m_useCount2 or 0,item.m_useCount3 or 0}}
                all[#all+1]=row
                if slot<=10 or slot>=34 then equipped[#equipped+1]=row
                elseif slot>=11 and slot<=14 then quiver[#quiver+1]=row
                elseif slot>=15 and slot<=17 then quick[#quick+1]=row
                elseif slot>=18 and slot<=33 then pack[#pack+1]=row end
            end
        end
    end
    return all,equipped,quick,quiver,pack
end
function Root:member(entry,long)
    local sprite=entry.sprite
    local all,equipped,quick,quiver,pack=self:items(sprite)
    local row={id=entry.id,name=nameOf(self.g,sprite),class=sprite.m_typeAI and sprite.m_typeAI.m_Class or 0,
        levels={stat(self.g,sprite,34),stat(self.g,sprite,68),stat(self.g,sprite,69)},
        hp=sprite.m_baseStats and sprite.m_baseStats.m_hitPoints or 0,maxHp=stat(self.g,sprite,1),ac=stat(self.g,sprite,2),
        dead=(sprite.m_baseStats and (sprite.m_baseStats.m_hitPoints or 0)<=0) or false,
        spells=self:spells(sprite),items=all}
    if long then
        row.x=sprite.m_pos.x;row.y=sprite.m_pos.y
        row.equipped=equipped;row.quick=quick;row.quiver=quiver;row.pack=pack
    end
    return row
end
function Root:members(party,long)
    local rows={}
    for _,entry in ipairs(party) do rows[#rows+1]=self:member(entry,long) end
    return rows
end
function Root:target(action)
    local object=action.m_acteeID
    local id=object and object.m_Instance
    if finite(id) and id>=0 then
        local target={id=id}
        local found=self.g.EEex_GameObject_Get(id)
        if found then
            local resref=resrefOf(found)
            if resref~='' then target.resref=resref end
        end
        return target
    end
    local point=action.m_dest
    if point and finite(point.x) and finite(point.y) then return {x=point.x,y=point.y} end
    return nil
end
function Root:resource(action)
    local resource=upper(action.m_string1 and action.m_string1.m_pchData and getString(action.m_string1.m_pchData))
    return M.spellOf(action,resource)
end
function Root:queue(sprite)
    local rows={}
    self.g.EEex_Utility_IterateCPtrList(sprite.m_queuedActions,function(action)
        rows[#rows+1]={id=action.m_actionID or -1,target=self:target(action),resource=self:resource(action)}
    end)
    return rows
end
function Root:foes(party)
    local seen,rows={},{}
    for _,member in ipairs(party) do
        local sprite=member.sprite
        self.g.EEex_Sprite_ForAllOfTypeStringInRange(sprite,'[ENEMY]',M.sightRange,function(other)
            if other and not seen[other.m_id] and other.m_id~=member.id
                and self.g.EEex_GameObject_IsSprite(other,true) and living(self.g,other)
                and other.m_typeAI and (other.m_typeAI.m_EnemyAlly or 0)>=200 then
                seen[other.m_id]=true
                rows[#rows+1]={id=other.m_id,resref=resrefOf(other),name=nameOf(self.g,other),x=other.m_pos.x,y=other.m_pos.y}
            end
        end,1,0)
    end
    table.sort(rows,function(a,b) return a.id<b.id end)
    return rows
end
function Root:endFight(reason,party,tick)
    local fight=self.fight
    if not fight then return end
    party=party or self:party()
    local ending=self:members(party,false)
    local short={}
    for _,member in ipairs(ending) do
        short[#short+1]={id=member.id,name=member.name,hp=member.hp,maxHp=member.maxHp,dead=member.dead}
    end
    local dead={}
    for _,member in ipairs(ending) do if member.dead then dead[#dead+1]=member.name end end
    local foesDead={}
    for _,foe in ipairs(fight.foes) do
        local found=self.g.EEex_GameObject_Get(foe.id)
        if not found or not self.g.EEex_GameObject_IsSprite(found,false) then foesDead[#foesDead+1]=foe.resref end
    end
    self:emit({k='fight',t=tick,phase='end',reason=reason,length=math.max(0,tick-fight.start),members=short,
        dead=dead,spent=M.spent(fight.members,ending),foesDead=foesDead})
    self.fight=nil;self:flush(true)
end
function Root:updateFight(party,tick)
    local foes=self:foes(party)
    if #foes>0 then
        if not self.fight then
            local members=self:members(party,true)
            self.fight={start=tick,lastSeen=tick,members=members,foes=foes}
            self:emit({k='fight',t=tick,phase='start',members=members,foes=foes})
        else self.fight.lastSeen=tick end
    elseif self.fight and tick-self.fight.lastSeen>=M.fightQuietTicks then self:endFight('quiet',party,tick) end
end
function Root:paused(tick)
    local screen=rawget(self.g,'worldScreen')
    if not screen or type(screen.CheckIfPaused)~='function' then return true end
    local paused=screen:CheckIfPaused()==true
    if self.wasPaused==nil or self.wasPaused~=paused then
        self.wasPaused=paused;self:emit({k='pause',t=tick,on=paused})
    end
    return paused
end
function Root:begin(party,tick)
    local game=gameOf(self.g)
    local names={};for _,entry in ipairs(party) do names[#names+1]=nameOf(self.g,entry.sprite) end
    self.sessionSeed={difficulty=game.m_options and game.m_options.m_nDifficultyLevel or 0,
        party=names,area=areaOf(party[1].sprite)}
    self:emit({k='session',t=tick,difficulty=self.sessionSeed.difficulty,party=names,area=self.sessionSeed.area})
    self.started=true
end
function Root:resetVolatile()
    self.queues={};self.area=nil;self.wasPaused=nil;self.fight=nil;self.lastFightScan=nil
end
function Root:initialized()
    self.initializedSeen=true
end
function Root:destroyed()
    if self.started and not self.disabled then
        -- Destroyed runs after the old game state has gone. Do not touch sprites here: all the
        -- session-local ids below are discarded, and a load-ended fight is explicitly partial.
        if self.fight then
            self:emit({k='fight',t=self.lastTick or 0,phase='end',reason='load',partial=true,
                length=math.max(0,(self.lastTick or 0)-self.fight.start),members={},dead={},spent={},foesDead={}})
        end
        self.reloadPending=true;self:flush(true)
    end
    self:resetVolatile()
end
function Root:attachEngine(tick)
    if self.engineAttached then return end
    local bgse=rawget(self.g,'BGSE')
    if type(bgse)~='table' then return end
    local function sink(tag)
        return function(row) self:guard('engine '..tag,function()
            self:emit({k='eng',t=self:now(),tag=tag,row=M.copy(row) or {}})
        end) end
    end
    if bgse.director and type(bgse.director.setSink)=='function' then bgse.director:setSink(sink('dir')) end
    if bgse.choice and type(bgse.choice.setSink)=='function' then
        bgse.choice:setSink(sink('ch'))
        if type(bgse.choice.setTrace)=='function' then bgse.choice:setTrace(true) end
    end
    self.engineAttached=true
end
function Root:tick()
    return self:guard('tick',function()
        self.tickCount=(self.tickCount or 0)+1
        local tick=self:now()
        local party=self:party()
        if #party==0 then return false end
        if not self.started then self:begin(party,tick)
        elseif self.reloadPending then
            self.reloadPending=false;self.loads=self.loads+1;self:resetVolatile()
            self:emit({k='load',t=tick,count=self.loads})
        end
        self:attachEngine(tick)
        local area=areaOf(party[1].sprite)
        if self.area~=nil and area~=self.area then self:endFight('area',party,tick);self:emit({k='area',t=tick,area=area}) end
        self.area=area
        local paused=self:paused(tick)
        for _,entry in ipairs(party) do
            local queue=self:queue(entry.sprite)
            if not M.sameQueue(self.queues[entry.id] or {},queue) then
                self.queues[entry.id]=M.cloneQueue(queue)
                self:emit({k='queue',t=tick,member=nameOf(self.g,entry.sprite),actions=queue})
            end
        end
        if not paused and (self.lastFightScan==nil or tick-self.lastFightScan>=M.ticksPerSecond) then
            self.lastFightScan=tick;self:updateFight(party,tick)
        end
        self:flush(false)
        return false -- invisible tick label
    end) or false
end
function Root:isParty(sprite)
    for _,entry in ipairs(self:party()) do if entry.id==sprite.m_id then return true end end
    return false
end
function Root:action(sprite,action)
    self:guard('action',function()
        if not self.started or not self:isParty(sprite) then return end
        local tick=self:now()
        self:emit({k='act',t=tick,member=nameOf(self.g,sprite),id=action.m_actionID or -1,
            target=self:target(action),resource=self:resource(action)})
    end)
end
function Root:worldInput()
    local check=rawget(self.g,'EEex_GameState_WouldWorldScreenProcessInput')
    local chitin=rawget(self.g,'EEex_EngineGlobal_CBaldurChitin')
    local globals=rawget(self.g,'EngineGlobals')
    if not chitin and globals then chitin=globals.g_pBaldurChitin end
    local world=rawget(self.g,'worldScreen')
    if type(check)~='function' or not chitin or type(chitin.GetActiveEngine)~='function'
        or chitin:GetActiveEngine()~=world then return false end
    local ok,ready=pcall(check)
    return ok and ready==true
end
function Root:key(key)
    self:guard('key',function()
        if not self.started or not self:worldInput() then return end
        local name=self.g.EEex_Key_GetName(key)
        if type(name)=='string' and #name>0 then self:emit({k='key',t=self:now(),name=name}) end
    end)
end
function Root:bar(config,state)
    self:guard('bar',function()
        if self.started then self:emit({k='bar',t=self:now(),config=M.copy(config),state=M.copy(state)}) end
    end)
end
function Root:inspect()
    return {disabled=self.disabled or false,ticks=self.tickCount or 0,loads=self.loads,
        rows=self.rows,started=self.started==true,fileOpen=self.file~=nil}
end

local TICK_MENU=[[
menu
{
    name "BGSE_RECORDER_TICK"
    ignoreEsc
    label
    {
        enabled "BGSE_Recorder_Tick()"
    }
}
]]

function M.new(g)
    return setmetatable({g=g,queues={},loads=0,rows=0,fileIndex=0,lastFlush=-1},Root)
end
function M.install(g)
    local enabled=rawget(g,'Infinity_GetINIValue')
    if type(enabled)=='function' and enabled('BGSE','Recorder',1)==0 then return nil end
    local prior=rawget(g,'BGSE_RECORDER')
    if type(prior)=='table' and prior.installed then return prior end
    local root=M.new(g);root.installed=true;g.BGSE_RECORDER=root
    g.BGSE_Recorder_Tick=function() return root:tick() end
    local function register(name,callback)
        local fn=rawget(g,name)
        if type(fn)~='function' then error(name..' unavailable') end
        fn(callback)
    end
    root:guard('install',function()
        register('EEex_Menu_AddAfterMainFileLoadedListener',function()
            root:guard('menu',function()
                g.EEex_Menu_Eval(TICK_MENU);root.menuLoaded=true
                if root.initializedSeen and type(g.Infinity_PushMenu)=='function' then g.Infinity_PushMenu('BGSE_RECORDER_TICK') end
            end)
        end)
        register('EEex_GameState_AddInitializedListener',function()
            root:guard('initialized',function()
                root:initialized()
                if root.menuLoaded and type(g.Infinity_PushMenu)=='function' then g.Infinity_PushMenu('BGSE_RECORDER_TICK') end
            end)
        end)
        register('EEex_GameState_AddDestroyedListener',function() root:guard('destroyed',function() root:destroyed() end) end)
        register('EEex_Action_AddSpriteStartedActionListener',function(sprite,action) root:action(sprite,action) end)
        register('EEex_Key_AddPressedListener',function(key) root:key(key) end)
        register('EEex_Actionbar_AddListener',function(config,state) root:bar(config,state) end)
    end)
    return root
end
return M
end
local ok,err=pcall(require("adapters.eeex.recorder").install,_G)
if not ok then print('[BGSE recorder] not installed: '..tostring(err)) end
